#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    scanf("%d", &n);

    vector<vector<long long>> a(n + 1, vector<long long>(n + 1));

    for (int k = 1; k <= n; ++k) {
        a[1][k] = 1;
        a[k][1] = 1;
    }

    for (int i = 2; i <= n; ++i)
        for (int j = 2; j <= n; ++j)
            a[i][j] = a[i - 1][j] + a[i][j - 1];

    printf("%lld", a[n][n]);
    return 0;
}

